import React, { useState, useEffect } from 'react';
import {
  Box,
  Paper,
  Typography,
  TextField,
  Button,
  Grid,
  Container,
  Alert,
  Snackbar,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Checkbox,
  FormControlLabel,
  Modal,
  IconButton,
  Stack,
  Select,
  MenuItem,
  FormControl,
  InputLabel
} from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';
import InfoIcon from '@mui/icons-material/Info';
import axios from 'axios';

function CostCalculator() {
  const defaultScaleConfig = {
    consumers_per_tenant: 3,
    total_tenants: 5000,
    endpoints_per_tenant: 10000
  };

  const defaultNetworkConfig = {
    api: {
      calls_per_day: 189,
      request_size_mb: 1.076
    },
    messages: {
      events_per_day: 100010,
      message_size_kb: 1
    }
  };

  const minimalConfig = {
    scale: {
      consumers_per_tenant: 1,
      total_tenants: 1,
      endpoints_per_tenant: 1
    },
    network_load: {
      api: {
        calls_per_day: 1,
        request_size_mb: 1
      },
      messages: {
        events_per_day: 1,
        message_size_kb: 1
      }
    }
  };

  const cloudProviders = {
    aws: {
      name: 'Amazon Web Services',
      regions: [
        { id: 'us-east-1', name: 'US East (N. Virginia)' },
        { id: 'us-west-2', name: 'US West (Oregon)' },
        { id: 'eu-west-1', name: 'Europe (Ireland)' },
        { id: 'ap-southeast-1', name: 'Asia Pacific (Singapore)' }
      ]
    },
    azure: {
      name: 'Microsoft Azure',
      regions: [
        { id: 'eastus', name: 'East US' },
        { id: 'westus2', name: 'West US 2' },
        { id: 'northeurope', name: 'North Europe' },
        { id: 'southeastasia', name: 'Southeast Asia' }
      ]
    },
    gcp: {
      name: 'Google Cloud Platform',
      regions: [
        { id: 'us-east1', name: 'South Carolina' },
        { id: 'us-west1', name: 'Oregon' },
        { id: 'europe-west1', name: 'Belgium' },
        { id: 'asia-southeast1', name: 'Singapore' }
      ]
    }
  };

  const [formData, setFormData] = useState({
    cloud_provider: 'aws',
    region: 'us-east-1',
    scale: {
      consumers_per_tenant: 3,
      total_tenants: 5000,
      endpoints_per_tenant: 10000
    }
  });

  const [scaleConfigEnabled, setScaleConfigEnabled] = useState(false);
  const [scaleConfigModalOpen, setScaleConfigModalOpen] = useState(false);
  const [networkLoadEnabled, setNetworkLoadEnabled] = useState(false);
  const [networkLoadModalOpen, setNetworkLoadModalOpen] = useState(false);
  const [networkLoadConfig, setNetworkLoadConfig] = useState(defaultNetworkConfig);

  const [costBreakdown, setCostBreakdown] = useState(null);
  const [notification, setNotification] = useState({
    open: false,
    message: '',
    severity: 'success'
  });

  const [costDetailModal, setCostDetailModal] = useState({
    open: false,
    title: '',
    details: null
  });

  const [cloudConfigModalOpen, setCloudConfigModalOpen] = useState(false);

  // Remove the problematic useEffect that's causing multiple recalculations
  useEffect(() => {
    console.log('Initializing form data');
    setFormData(prev => ({
      ...prev,
      cloud_provider: 'aws',
      region: 'us-east-1',
      scale: {
        consumers_per_tenant: 3,
        total_tenants: 5000,
        endpoints_per_tenant: 10000
      }
    }));
  }, []);

  // Effect to handle scale config changes
  useEffect(() => {
    setFormData(prev => ({
      ...prev,
      scale: scaleConfigEnabled ? defaultScaleConfig : minimalConfig.scale
    }));
  }, [scaleConfigEnabled]);

  // Effect to handle network load config changes
  useEffect(() => {
    setNetworkLoadConfig(networkLoadEnabled ? defaultNetworkConfig : minimalConfig.network_load);
  }, [networkLoadEnabled]);

  // Remove the useEffect that triggers calculateCosts on formData changes

  const handleInputChange = (field, value) => {
    setFormData(prev => ({
      ...prev,
      scale: {
        ...prev.scale,
        [field]: parseInt(value) || 0
      }
    }));
  };

  const handleScaleConfigChange = (event) => {
    setScaleConfigEnabled(event.target.checked);
    if (event.target.checked) {
      setScaleConfigModalOpen(true);
    }
  };

  const handleNetworkLoadChange = (event) => {
    setNetworkLoadEnabled(event.target.checked);
    if (event.target.checked) {
      setNetworkLoadModalOpen(true);
    }
  };

  const handleNetworkConfigChange = (category, field, value) => {
    setNetworkLoadConfig(prev => ({
      ...prev,
      [category]: {
        ...prev[category],
        [field]: parseFloat(value) || 0
      }
    }));
  };

  const handleRegionChange = (event) => {
    const newRegion = event.target.value;
    console.log('Region changing to:', newRegion);

    // Update form data with new region
    setFormData(prevData => {
      const updatedData = {
        ...prevData,
        region: newRegion
      };
      console.log('Updated form data:', updatedData);
      return updatedData;
    });

    // Close modal
    setCloudConfigModalOpen(false);
  };

  const handleProviderChange = (event) => {
    const newProvider = event.target.value;
    console.log('Provider changing to:', newProvider);
    const defaultRegion = cloudProviders[newProvider].regions[0].id;

    setFormData(prev => {
      const updated = {
        ...prev,
        cloud_provider: newProvider,
        region: defaultRegion
      };
      console.log('Updated form data with new provider:', updated);
      return updated;
    });

    // Close modal
    setCloudConfigModalOpen(false);
  };

  const modalStyle = {
    position: 'absolute',
    top: '50%',
    left: '50%',
    transform: 'translate(-50%, -50%)',
    width: '80%',
    maxWidth: 800,
    bgcolor: 'background.paper',
    boxShadow: 24,
    p: 4,
    borderRadius: 2,
    maxHeight: '90vh',
    overflow: 'auto'
  };

  const calculateCosts = async () => {
    try {
      const requestData = {
        scale: {
          consumers_per_tenant: formData.scale.consumers_per_tenant,
          total_tenants: formData.scale.total_tenants,
          endpoints_per_tenant: formData.scale.endpoints_per_tenant
        },
        cloud_provider: formData.cloud_provider,
        region: formData.region,
        deployment: {
          num_tenants: formData.scale.total_tenants,
          consumers_per_tenant: formData.scale.consumers_per_tenant,
          endpoints_per_tenant: formData.scale.endpoints_per_tenant,
          messages_per_day: networkLoadEnabled ? networkLoadConfig.messages.events_per_day : 1,
          api_requests_per_day: networkLoadEnabled ? networkLoadConfig.api.calls_per_day : 1,
          data_throughput_gb: networkLoadEnabled ? 
            ((networkLoadConfig.api.calls_per_day * networkLoadConfig.api.request_size_mb / 1024) +
             (networkLoadConfig.messages.events_per_day * networkLoadConfig.messages.message_size_kb / (1024 * 1024))) : 0.1,
          data_per_tenant_gb: 1,
          region: formData.region,
          network_metrics: {
            message_size_kb: networkLoadEnabled ? networkLoadConfig.messages.message_size_kb : 1
          }
        }
      };

      console.log('Sending request:', JSON.stringify(requestData, null, 2));

      const response = await axios.post('http://localhost:8000/calculate-cost', requestData);
      console.log('Received response:', JSON.stringify(response.data, null, 2));

      setCostBreakdown(response.data);
      setNotification({
        open: true,
        message: 'Cost calculation successful!',
        severity: 'success'
      });
    } catch (error) {
      console.error('Error calculating costs:', error);
      setNotification({
        open: true,
        message: 'Error calculating costs: ' + (error.response?.data?.detail || error.message),
        severity: 'error'
      });
    }
  };

  const handleCloseNotification = () => {
    setNotification({ ...notification, open: false });
  };

  const formatCurrency = (value) => {
    if (value === undefined || value === null) {
      return '$0.00';
    }
    return `$${Number(value).toFixed(2)}`;
  };

  const getStorageDetails = (storage) => {
    if (!storage) return [];

    return [
      {
        title: 'DynamoDB Costs',
        items: [
          { label: 'Storage', value: `${(storage.dynamodb_cost / 3).toFixed(2)} (Monthly storage cost)` },
          { label: 'Write Requests', value: `${(storage.dynamodb_cost / 3).toFixed(2)} (Monthly write operations)` },
          { label: 'Read Requests', value: `${(storage.dynamodb_cost / 3).toFixed(2)} (Monthly read operations)` },
          { label: 'Total', value: formatCurrency(storage.dynamodb_cost) }
        ]
      },
      {
        title: 'S3 Costs',
        items: [
          { label: 'Storage', value: `${(storage.s3_cost * 0.8).toFixed(2)} (Monthly storage cost)` },
          { label: 'PUT Requests', value: `${(storage.s3_cost * 0.1).toFixed(2)} (Monthly PUT operations)` },
          { label: 'GET Requests', value: `${(storage.s3_cost * 0.1).toFixed(2)} (Monthly GET operations)` },
          { label: 'Total', value: formatCurrency(storage.s3_cost) }
        ]
      }
    ];
  };

  const getContainerDetails = (container) => {
    if (!container) return [];

    return [
      {
        title: 'EKS Costs',
        items: [
          { label: 'Cluster Cost', value: `${(container * 0.3).toFixed(2)} (Monthly cluster management)` },
          { label: 'Node Groups', value: `${(container * 0.7).toFixed(2)} (EC2 instances cost)` },
          { label: 'Total', value: formatCurrency(container) }
        ]
      }
    ];
  };

  const getNetworkDetails = (network) => {
    if (!network) return [];

    return [
      {
        title: 'Data Transfer Costs',
        items: [
          { label: 'Inbound Traffic', value: 'Free' },
          { label: 'Outbound Traffic', value: formatCurrency(network.throughput_cost) },
          { label: 'Total', value: formatCurrency(network.throughput_cost) }
        ]
      },
      {
        title: 'MSK Costs',
        items: [
          { label: 'Broker Hours', value: `${(network.msk_cost * 0.7).toFixed(2)} (Broker instance costs)` },
          { label: 'Storage', value: `${(network.msk_cost * 0.3).toFixed(2)} (Message retention storage)` },
          { label: 'Total', value: formatCurrency(network.msk_cost) }
        ]
      }
    ];
  };

  const getPxGridDetails = (pxgrid_cost) => {
    if (!pxgrid_cost) return [];

    return [
      {
        title: 'PxGrid Costs',
        items: [
          { label: 'Message Publishing', value: `${(pxgrid_cost * 0.7).toFixed(2)} (Monthly message costs)` },
          { label: 'API Load', value: `${(pxgrid_cost * 0.3).toFixed(2)} (Monthly API costs)` },
          { label: 'Total', value: formatCurrency(pxgrid_cost) }
        ]
      }
    ];
  };

  const handleShowDetails = (type, data) => {
    let details;
    let title;

    switch (type) {
      case 'pxgrid':
        details = getPxGridDetails(data);
        title = 'PxGrid Cost Details';
        break;
      case 'storage':
        details = getStorageDetails(data);
        title = 'Storage Cost Details';
        break;
      case 'container':
        details = getContainerDetails(data);
        title = 'Container Infrastructure Cost Details';
        break;
      case 'network':
        details = getNetworkDetails(data);
        title = 'Network Cost Details';
        break;
      default:
        details = [];
    }

    setCostDetailModal({
      open: true,
      title,
      details
    });
  };

  const CostDetailModal = () => (
    <Modal
      open={costDetailModal.open}
      onClose={() => setCostDetailModal({ ...costDetailModal, open: false })}
    >
      <Box sx={modalStyle}>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
          <Typography variant="h6">{costDetailModal.title}</Typography>
          <IconButton onClick={() => setCostDetailModal({ ...costDetailModal, open: false })} size="small">
            <CloseIcon />
          </IconButton>
        </Box>

        {costDetailModal.details?.map((section, idx) => (
          <Box key={idx} sx={{ mb: 3 }}>
            <Typography variant="subtitle1" gutterBottom>{section.title}</Typography>
            <TableContainer component={Paper}>
              <Table size="small">
                <TableBody>
                  {section.items.map((item, i) => (
                    <TableRow key={i}>
                      <TableCell>{item.label}</TableCell>
                      <TableCell align="right">{item.value}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Box>
        ))}
      </Box>
    </Modal>
  );

  return (
    <Container maxWidth="lg">
      <Paper elevation={3} sx={{ p: 3, mt: 3 }}>
        <Typography variant="h4" gutterBottom>
          PxGrid Cloud Cost Calculator
        </Typography>

        <Box sx={{ mb: 4 }}>
          <Stack spacing={2}>
            <FormControlLabel
              control={
                <Button
                  variant="outlined"
                  onClick={() => setCloudConfigModalOpen(true)}
                  startIcon={<InfoIcon />}
                >
                  {`${cloudProviders[formData.cloud_provider].name} - ${
                    cloudProviders[formData.cloud_provider].regions.find(
                      r => r.id === formData.region
                    )?.name
                  }`}
                </Button>
              }
              label="Cloud Provider & Region"
              labelPlacement="start"
              sx={{ 
                mx: 0,
                justifyContent: 'space-between',
                width: '100%'
              }}
            />

            <FormControlLabel
              control={
                <Checkbox
                  checked={scaleConfigEnabled}
                  onChange={handleScaleConfigChange}
                  color="primary"
                />
              }
              label={
                <Box>
                  <Typography variant="body1">Configure Scale Parameters</Typography>
                  <Typography variant="caption" color="text.secondary">
                    {scaleConfigEnabled ? 'Using custom configuration' : 'Using minimal values (1)'}
                  </Typography>
                </Box>
              }
            />

            <FormControlLabel
              control={
                <Checkbox
                  checked={networkLoadEnabled}
                  onChange={handleNetworkLoadChange}
                  color="primary"
                />
              }
              label={
                <Box>
                  <Typography variant="body1">Configure Network Load</Typography>
                  <Typography variant="caption" color="text.secondary">
                    {networkLoadEnabled ? 'Using custom configuration' : 'Using minimal values (1)'}
                  </Typography>
                </Box>
              }
            />
          </Stack>

          <Modal
            open={scaleConfigModalOpen}
            onClose={() => setScaleConfigModalOpen(false)}
          >
            <Box sx={modalStyle}>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                <Typography variant="h6">Scale Parameters Configuration</Typography>
                <IconButton onClick={() => setScaleConfigModalOpen(false)} size="small">
                  <CloseIcon />
                </IconButton>
              </Box>

              <TableContainer component={Paper} sx={{ mb: 3 }}>
                <Table>
                  <TableHead>
                    <TableRow>
                      <TableCell>S.No</TableCell>
                      <TableCell>Scale Parameters</TableCell>
                      <TableCell>Count</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    <TableRow>
                      <TableCell>1</TableCell>
                      <TableCell>Cloud consumer per Tenant</TableCell>
                      <TableCell>
                        <TextField
                          type="number"
                          value={formData.scale.consumers_per_tenant}
                          onChange={(e) => handleInputChange('consumers_per_tenant', e.target.value)}
                          size="small"
                          inputProps={{ min: 1 }}
                        />
                      </TableCell>
                    </TableRow>
                    <TableRow>
                      <TableCell>2</TableCell>
                      <TableCell>Total Tenant</TableCell>
                      <TableCell>
                        <TextField
                          type="number"
                          value={formData.scale.total_tenants}
                          onChange={(e) => handleInputChange('total_tenants', e.target.value)}
                          size="small"
                          inputProps={{ min: 1 }}
                        />
                      </TableCell>
                    </TableRow>
                    <TableRow>
                      <TableCell>3</TableCell>
                      <TableCell>Total End-points per Tenant</TableCell>
                      <TableCell>
                        <TextField
                          type="number"
                          value={formData.scale.endpoints_per_tenant}
                          onChange={(e) => handleInputChange('endpoints_per_tenant', e.target.value)}
                          size="small"
                          inputProps={{ min: 1 }}
                        />
                      </TableCell>
                    </TableRow>
                  </TableBody>
                </Table>
              </TableContainer>

              <Box sx={{ mt: 3, display: 'flex', justifyContent: 'flex-end' }}>
                <Button
                  variant="contained"
                  onClick={() => setScaleConfigModalOpen(false)}
                >
                  Save Configuration
                </Button>
              </Box>
            </Box>
          </Modal>

          <Modal
            open={networkLoadModalOpen}
            onClose={() => setNetworkLoadModalOpen(false)}
          >
            <Box sx={modalStyle}>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                <Typography variant="h6">Network Load Configuration</Typography>
                <IconButton onClick={() => setNetworkLoadModalOpen(false)} size="small">
                  <CloseIcon />
                </IconButton>
              </Box>

              <Grid container spacing={3}>
                <Grid item xs={12}>
                  <Typography variant="subtitle1" gutterBottom>API Configuration</Typography>
                  <Grid container spacing={2}>
                    <Grid item xs={12} md={6}>
                      <TextField
                        fullWidth
                        label="Average API Calls per Day"
                        type="number"
                        value={networkLoadConfig.api.calls_per_day}
                        onChange={(e) => handleNetworkConfigChange('api', 'calls_per_day', e.target.value)}
                        size="small"
                      />
                    </Grid>
                    <Grid item xs={12} md={6}>
                      <TextField
                        fullWidth
                        label="Average Request Size (MB)"
                        type="number"
                        value={networkLoadConfig.api.request_size_mb}
                        onChange={(e) => handleNetworkConfigChange('api', 'request_size_mb', e.target.value)}
                        size="small"
                      />
                    </Grid>
                  </Grid>
                </Grid>

                <Grid item xs={12}>
                  <Typography variant="subtitle1" gutterBottom>Message Events Configuration</Typography>
                  <Grid container spacing={2}>
                    <Grid item xs={12} md={6}>
                      <TextField
                        fullWidth
                        label="Average Events per Day"
                        type="number"
                        value={networkLoadConfig.messages.events_per_day}
                        onChange={(e) => handleNetworkConfigChange('messages', 'events_per_day', e.target.value)}
                        size="small"
                      />
                    </Grid>
                    <Grid item xs={12} md={6}>
                      <TextField
                        fullWidth
                        label="Average Message Size (KB)"
                        type="number"
                        value={networkLoadConfig.messages.message_size_kb}
                        onChange={(e) => handleNetworkConfigChange('messages', 'message_size_kb', e.target.value)}
                        size="small"
                      />
                    </Grid>
                  </Grid>
                </Grid>
              </Grid>

              <Box sx={{ mt: 3, display: 'flex', justifyContent: 'flex-end' }}>
                <Button
                  variant="contained"
                  onClick={() => setNetworkLoadModalOpen(false)}
                >
                  Save Configuration
                </Button>
              </Box>
            </Box>
          </Modal>

          <Modal
            open={cloudConfigModalOpen}
            onClose={() => setCloudConfigModalOpen(false)}
          >
            <Box sx={modalStyle}>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                <Typography variant="h6">Cloud Provider & Region Configuration</Typography>
                <IconButton onClick={() => setCloudConfigModalOpen(false)} size="small">
                  <CloseIcon />
                </IconButton>
              </Box>

              <Grid container spacing={3}>
                <Grid item xs={12}>
                  <FormControl fullWidth>
                    <InputLabel>Cloud Provider</InputLabel>
                    <Select
                      value={formData.cloud_provider}
                      onChange={handleProviderChange}
                      label="Cloud Provider"
                    >
                      {Object.entries(cloudProviders).map(([key, provider]) => (
                        <MenuItem key={key} value={key}>
                          {provider.name}
                        </MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                </Grid>

                <Grid item xs={12}>
                  <FormControl fullWidth>
                    <InputLabel>Region</InputLabel>
                    <Select
                      value={formData.region}
                      onChange={handleRegionChange}
                      label="Region"
                    >
                      {cloudProviders[formData.cloud_provider].regions.map((region) => (
                        <MenuItem key={region.id} value={region.id}>
                          {region.name} ({region.id}) - {region.id === 'us-east-1' ? '1.0x' :
                            region.id === 'us-west-2' ? '1.05x' :
                            region.id === 'eu-west-1' ? '1.12x' :
                            region.id === 'ap-southeast-1' ? '1.15x' : '1.0x'} base price
                        </MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                </Grid>

                <Grid item xs={12}>
                  <Typography variant="body2" color="text.secondary">
                    Current Region: {cloudProviders[formData.cloud_provider].regions.find(r => r.id === formData.region)?.name}
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    Price Multiplier: {formData.region === 'us-east-1' ? '1.0x' :
                      formData.region === 'us-west-2' ? '1.05x' :
                      formData.region === 'eu-west-1' ? '1.12x' :
                      formData.region === 'ap-southeast-1' ? '1.15x' : '1.0x'} base price
                  </Typography>
                </Grid>
              </Grid>

              <Box sx={{ mt: 3, display: 'flex', justifyContent: 'flex-end', gap: 2 }}>
                <Button
                  variant="outlined"
                  onClick={() => {
                    console.log('Cancelling cloud config changes');
                    setCloudConfigModalOpen(false);
                  }}
                >
                  Cancel
                </Button>
                <Button
                  variant="contained"
                  onClick={() => {
                    console.log('Saving cloud config with region:', formData.region);
                    setCloudConfigModalOpen(false);
                    calculateCosts();
                  }}
                >
                  Save & Calculate
                </Button>
              </Box>
            </Box>
          </Modal>

          <Box sx={{ mt: 3 }}>
            <Button
              variant="contained"
              color="primary"
              size="large"
              onClick={calculateCosts}
            >
              Calculate Costs
            </Button>
          </Box>
        </Box>

        {costBreakdown && (
          <Box sx={{ mt: 4 }}>
            <Typography variant="h5" gutterBottom>Cost Breakdown (Monthly)</Typography>
            <Grid container spacing={3}>
              <Grid item xs={12} md={6}>
                <Paper 
                  elevation={2} 
                  sx={{ 
                    p: 2, 
                    cursor: 'pointer',
                    '&:hover': { bgcolor: 'action.hover' }
                  }}
                  onClick={() => handleShowDetails('pxgrid', costBreakdown?.breakdown?.pxgrid_cost)}
                >
                  <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                    <Typography variant="subtitle1">PxGrid Costs</Typography>
                    <InfoIcon color="action" fontSize="small" />
                  </Box>
                  <Typography variant="h6">{formatCurrency(costBreakdown?.breakdown?.pxgrid_cost)}</Typography>
                </Paper>
              </Grid>
              <Grid item xs={12} md={6}>
                <Paper 
                  elevation={2} 
                  sx={{ 
                    p: 2, 
                    cursor: 'pointer',
                    '&:hover': { bgcolor: 'action.hover' }
                  }}
                  onClick={() => handleShowDetails('storage', costBreakdown?.breakdown?.storage)}
                >
                  <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                    <Typography variant="subtitle1">Storage Costs</Typography>
                    <InfoIcon color="action" fontSize="small" />
                  </Box>
                  <Typography variant="body2">DynamoDB: {formatCurrency(costBreakdown?.breakdown?.storage?.dynamodb_cost)}</Typography>
                  <Typography variant="body2">S3: {formatCurrency(costBreakdown?.breakdown?.storage?.s3_cost)}</Typography>
                </Paper>
              </Grid>
              <Grid item xs={12} md={6}>
                <Paper 
                  elevation={2} 
                  sx={{ 
                    p: 2, 
                    cursor: 'pointer',
                    '&:hover': { bgcolor: 'action.hover' }
                  }}
                  onClick={() => handleShowDetails('container', costBreakdown?.breakdown?.container_cost)}
                >
                  <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                    <Typography variant="subtitle1">Container Costs</Typography>
                    <InfoIcon color="action" fontSize="small" />
                  </Box>
                  <Typography variant="h6">{formatCurrency(costBreakdown?.breakdown?.container_cost)}</Typography>
                </Paper>
              </Grid>
              <Grid item xs={12} md={6}>
                <Paper 
                  elevation={2} 
                  sx={{ 
                    p: 2, 
                    cursor: 'pointer',
                    '&:hover': { bgcolor: 'action.hover' }
                  }}
                  onClick={() => handleShowDetails('network', costBreakdown?.breakdown?.network)}
                >
                  <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                    <Typography variant="subtitle1">Network Costs</Typography>
                    <InfoIcon color="action" fontSize="small" />
                  </Box>
                  <Typography variant="body2">Throughput: {formatCurrency(costBreakdown?.breakdown?.network?.throughput_cost)}</Typography>
                  <Typography variant="body2">MSK: {formatCurrency(costBreakdown?.breakdown?.network?.msk_cost)}</Typography>
                </Paper>
              </Grid>
              <Grid item xs={12}>
                <Paper elevation={3} sx={{ p: 2, bgcolor: 'primary.light', color: 'primary.contrastText' }}>
                  <Typography variant="h6">Total Monthly Cost: {formatCurrency(costBreakdown?.total_cost)}</Typography>
                  <Typography variant="subtitle1">Cost per Tenant: {formatCurrency(costBreakdown?.monthly_cost_per_tenant)}</Typography>
                </Paper>
              </Grid>
            </Grid>

            <CostDetailModal />
          </Box>
        )}

        <Snackbar
          open={notification.open}
          autoHideDuration={6000}
          onClose={handleCloseNotification}
        >
          <Alert onClose={handleCloseNotification} severity={notification.severity}>
            {notification.message}
          </Alert>
        </Snackbar>
      </Paper>
    </Container>
  );
}

export default CostCalculator;
